import{_ as l,a0 as t,w as d,s as o,ao as h,I as p,x as a,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"SDKMAN：轻松管理多个软件开发套件 (SDK) 的命令行工具 | LCTT x X-CMD","titleTemplate":false,"description":"SDKMAN：轻松管理多个软件开发套件 (SDK) 的命令行工具 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"SDKMAN：轻松管理多个软件开发套件 (SDK) 的命令行工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"SDKMAN：轻松管理多个软件开发套件 (SDK) 的命令行工具 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20180803 SDKMAN - A CLI Tool To Easily Manage Multiple Software Development Kits","title":"SDKMAN：轻松管理多个软件开发套件 (SDK) 的命令行工具","tag":"201811","desc":""},"relativePath":"201811/20180803 SDKMAN - A CLI Tool To Easily Manage Multiple Software Development Kits.md","filePath":"[post].md"}'),c={name:"201811/20180803 SDKMAN - A CLI Tool To Easily Manage Multiple Software Development Kits.md"};function r(g,s,k,u,b,f){const n=t("Link");return d(),o("div",null,[s[15]||(s[15]=h(`<h1 id="sdkman-轻松管理多个软件开发套件-sdk-的命令行工具" tabindex="-1">SDKMAN：轻松管理多个软件开发套件 (SDK) 的命令行工具 <a class="header-anchor" href="#sdkman-轻松管理多个软件开发套件-sdk-的命令行工具" aria-label="Permalink to “SDKMAN：轻松管理多个软件开发套件 (SDK) 的命令行工具”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/sdkman-720x340.png" alt=""></p><p>你是否是一个经常在不同的 SDK 下安装和测试应用的开发者？我有一个好消息要告诉你！给你介绍一下 <strong>SDKMAN</strong>，一个可以帮你轻松管理多个 SDK 的命令行工具。它为安装、切换、列出和移除 SDK 提供了一个简便的方式。有了 SDKMAN，你可以在任何类 Unix 的操作系统上轻松地并行管理多个 SDK 的多个版本。它允许开发者为 JVM 安装不同的 SDK，例如 Java、Groovy、Scala、Kotlin 和 Ceylon、Ant、Gradle、Grails、Maven、SBT、Spark、Spring Boot、Vert.x，以及许多其他支持的 SDK。SDKMAN 是免费、轻量、开源、使用 <strong>Bash</strong> 编写的程序。</p><h3 id="安装-sdkman" tabindex="-1">安装 SDKMAN <a class="header-anchor" href="#安装-sdkman" aria-label="Permalink to “安装 SDKMAN”">​</a></h3><p>安装 SDKMAN 很简单。首先，确保你已经安装了 <code>zip</code> 和 <code>unzip</code> 这两个应用。它们在大多数的 Linux 发行版的默认仓库中。<br> 例如，在基于 Debian 的系统上安装 unzip，只需要运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install zip unzip</span></span></code></pre></div><p>然后使用下面的命令安装 SDKMAN：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -s &quot;https://get.sdkman.io&quot; | bash</span></span></code></pre></div><p>在安装完成之后，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source &quot;$HOME/.sdkman/bin/sdkman-init.sh&quot;</span></span></code></pre></div><p>如果你希望自定义安装到其他位置，例如 <code>/usr/local/</code>，你可以这样做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export SDKMAN_DIR=&quot;/usr/local/sdkman&quot; &amp;&amp; curl -s &quot;https://get.sdkman.io&quot; | bash</span></span></code></pre></div><p>确保你的用户有足够的权限访问这个目录。</p><p>最后，在安装完成后使用下面的命令检查一下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk version</span></span>
<span class="line"><span>==== BROADCAST =================================================================</span></span>
<span class="line"><span>* 01/08/18: Kotlin 1.2.60 released on SDKMAN! #kotlin</span></span>
<span class="line"><span>* 31/07/18: Sbt 1.2.0 released on SDKMAN! #sbt</span></span>
<span class="line"><span>* 31/07/18: Infrastructor 0.2.1 released on SDKMAN! #infrastructor</span></span>
<span class="line"><span>================================================================================</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SDKMAN 5.7.2+323</span></span></code></pre></div><p>恭喜你！SDKMAN 已经安装完成了。让我们接下来看如何安装和管理 SDKs 吧。</p><h3 id="管理多个-sdk" tabindex="-1">管理多个 SDK <a class="header-anchor" href="#管理多个-sdk" aria-label="Permalink to “管理多个 SDK”">​</a></h3><p>查看可用的 SDK 清单，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk list</span></span></code></pre></div><p>将会输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>================================================================================</span></span>
<span class="line"><span>Available Candidates</span></span>
<span class="line"><span>================================================================================</span></span>
<span class="line"><span>q-quit /-search down</span></span>
<span class="line"><span>j-down ?-search up</span></span>
<span class="line"><span>k-up h-help</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--------------------------------------------------------------------------------</span></span>
<span class="line"><span>Ant (1.10.1) https://ant.apache.org/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Apache Ant is a Java library and command-line tool whose mission is to drive</span></span>
<span class="line"><span>processes described in build files as targets and extension points dependent</span></span>
<span class="line"><span>upon each other. The main known usage of Ant is the build of Java applications.</span></span>
<span class="line"><span>Ant supplies a number of built-in tasks allowing to compile, assemble, test and</span></span>
<span class="line"><span>run Java applications. Ant can also be used effectively to build non Java</span></span>
<span class="line"><span>applications, for instance C or C++ applications. More generally, Ant can be</span></span>
<span class="line"><span>used to pilot any type of process which can be described in terms of targets and</span></span>
<span class="line"><span>tasks.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>: $ sdk install ant</span></span></code></pre></div><p>就像你看到的，SDK 每次列出众多 SDK 中的一个，以及该 SDK 的描述信息、官方网址和安装命令。按回车键继续下一个。</p><p>安装一个新的 SDK，例如 Java JDK，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk install java</span></span></code></pre></div><p>将会输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Downloading: java 8.0.172-zulu</span></span>
<span class="line"><span></span></span>
<span class="line"><span>In progress...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>######################################################################################## 100.0%</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Repackaging Java 8.0.172-zulu...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Done repackaging...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Installing: java 8.0.172-zulu</span></span>
<span class="line"><span>Done installing!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Setting java 8.0.172-zulu as default.</span></span></code></pre></div><p>如果你安装了多个 SDK，它将会提示你是否想要将当前安装的版本设置为 <strong>默认版本</strong>。回答 <code>Yes</code> 将会把当前版本设置为默认版本。</p><p>使用以下命令安装一个 SDK 的其他版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk install ant 1.10.1</span></span></code></pre></div><p>如果你之前已经在本地安装了一个 SDK，你可以像下面这样设置它为本地版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk install groovy 3.0.0-SNAPSHOT /path/to/groovy-3.0.0-SNAPSHOT</span></span></code></pre></div><p>列出一个 SDK 的多个版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk list ant</span></span></code></pre></div><p>将会输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>================================================================================</span></span>
<span class="line"><span>Available Ant Versions</span></span>
<span class="line"><span>================================================================================</span></span>
<span class="line"><span>&gt; * 1.10.1</span></span>
<span class="line"><span>1.10.0</span></span>
<span class="line"><span>1.9.9</span></span>
<span class="line"><span>1.9.8</span></span>
<span class="line"><span>1.9.7</span></span>
<span class="line"><span></span></span>
<span class="line"><span>================================================================================</span></span>
<span class="line"><span>+ - local version</span></span>
<span class="line"><span>* - installed</span></span>
<span class="line"><span>&gt; - currently in use</span></span>
<span class="line"><span>================================================================================</span></span></code></pre></div><p>像我之前说的，如果你安装了多个版本，SDKMAN 会提示你是否想要设置当前安装的版本为 <strong>默认版本</strong>。你可以回答 Yes 设置它为默认版本。当然，你也可以在稍后使用下面的命令设置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk default ant 1.9.9</span></span></code></pre></div><p>上面的命令将会设置 Apache Ant 1.9.9 为默认版本。</p><p>你可以根据自己的需要选择使用任何已安装的 SDK 版本，仅需运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk use ant 1.9.9</span></span></code></pre></div><p>检查某个具体 SDK 当前的版本号，例如 Java，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk current java</span></span>
<span class="line"><span>Using java version 8.0.172-zulu</span></span></code></pre></div><p>检查所有当下在使用的 SDK 版本号，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk current</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Using:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ant: 1.10.1</span></span>
<span class="line"><span>java: 8.0.172-zulu</span></span></code></pre></div><p>升级过时的 SDK，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk upgrade scala</span></span></code></pre></div><p>你也可以检查所有的 SDK 中还有哪些是过时的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk upgrade</span></span></code></pre></div><p>SDKMAN 有离线模式，可以让 SDKMAN 在离线时也正常运作。你可以使用下面的命令在任何时间开启或者关闭离线模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk offline enable</span></span>
<span class="line"><span>$ sdk offline disable</span></span></code></pre></div><p>要移除已安装的 SDK，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk uninstall ant 1.9.9</span></span></code></pre></div><p>要了解更多的细节，参阅帮助章节。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk help</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage: sdk &lt;command&gt; [candidate] [version]</span></span>
<span class="line"><span>sdk offline &lt;enable|disable&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>commands:</span></span>
<span class="line"><span>install or i &lt;candidate&gt; [version]</span></span>
<span class="line"><span>uninstall or rm &lt;candidate&gt; &lt;version&gt;</span></span>
<span class="line"><span>list or ls [candidate]</span></span>
<span class="line"><span>use or u &lt;candidate&gt; [version]</span></span>
<span class="line"><span>default or d &lt;candidate&gt; [version]</span></span>
<span class="line"><span>current or c [candidate]</span></span>
<span class="line"><span>upgrade or ug [candidate]</span></span>
<span class="line"><span>version or v</span></span>
<span class="line"><span>broadcast or b</span></span>
<span class="line"><span>help or h</span></span>
<span class="line"><span>offline [enable|disable]</span></span>
<span class="line"><span>selfupdate [force]</span></span>
<span class="line"><span>update</span></span>
<span class="line"><span>flush &lt;broadcast|archives|temp&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>candidate : the SDK to install: groovy, scala, grails, gradle, kotlin, etc.</span></span>
<span class="line"><span>                 use list command for comprehensive list of candidates</span></span>
<span class="line"><span>                 eg: $ sdk list</span></span>
<span class="line"><span></span></span>
<span class="line"><span>version : where optional, defaults to latest stable if not provided</span></span>
<span class="line"><span>             eg: $ sdk install groovy</span></span></code></pre></div><h3 id="更新-sdkman" tabindex="-1">更新 SDKMAN <a class="header-anchor" href="#更新-sdkman" aria-label="Permalink to “更新 SDKMAN”">​</a></h3><p>如果有可用的新版本，可以使用下面的命令安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk selfupdate</span></span></code></pre></div><p>SDKMAN 会定期检查更新，并给出让你了解如何更新的指令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>WARNING: SDKMAN is out-of-date and requires an update.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sdk update</span></span>
<span class="line"><span>Adding new candidates(s): scala</span></span></code></pre></div><h3 id="清除缓存" tabindex="-1">清除缓存 <a class="header-anchor" href="#清除缓存" aria-label="Permalink to “清除缓存”">​</a></h3><p>建议时不时的清理缓存（包括那些下载的 SDK 的二进制文件）。仅需运行下面的命令就可以了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk flush archives</span></span></code></pre></div><p>它也可以用于清理空的文件夹，节省一点空间：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sdk flush temp</span></span></code></pre></div><h3 id="卸载-sdkman" tabindex="-1">卸载 SDKMAN <a class="header-anchor" href="#卸载-sdkman" aria-label="Permalink to “卸载 SDKMAN”">​</a></h3><p>如果你觉得不需要或者不喜欢 SDKMAN，可以使用下面的命令删除。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar zcvf ~/sdkman-backup_$(date +%F-%kh%M).tar.gz -C ~/ .sdkman</span></span>
<span class="line"><span>$ rm -rf ~/.sdkman</span></span></code></pre></div><p>最后打开你的 <code>.bashrc</code>、<code>.bash_profile</code> 和/或者 <code>.profile</code>，找到并删除下面这几行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#THIS MUST BE AT THE END OF THE FILE FOR SDKMAN TO WORK!!!</span></span>
<span class="line"><span>export SDKMAN_DIR=&quot;/home/sk/.sdkman&quot;</span></span>
<span class="line"><span>[[ -s &quot;/home/sk/.sdkman/bin/sdkman-init.sh&quot; ]] &amp;&amp; source &quot;/home/sk/.sdkman/bin/sdkman-init.sh&quot;</span></span></code></pre></div><p>如果你使用的是 ZSH，就从 <code>.zshrc</code> 中删除上面这一行。</p><p>这就是所有的内容了。我希望 SDKMAN 可以帮到你。还有更多的干货即将到来。敬请期待！</p><p>祝近祺！</p><p>：）</p><hr>`,74)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),i(n,{href:"https://www.ostechnix.com/sdkman-a-cli-tool-to-easily-manage-multiple-software-development-kits/"},{default:e(()=>[...s[0]||(s[0]=[a("https://www.ostechnix.com/sdkman-a-cli-tool-to-easily-manage-multiple-software-development-kits/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),i(n,{href:"https://www.ostechnix.com/author/sk/"},{default:e(()=>[...s[2]||(s[2]=[a("SK",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),i(n,{href:"https://github.com/dianbanjiu"},{default:e(()=>[...s[4]||(s[4]=[a("dianbanjiu",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const S=l(c,[["render",r]]);export{y as __pageData,S as default};
